+    }
+    
+    printf("\033[2J\033[H");
+    
+    if (message != NULL) {
+        printf("\033[?1049h");
+        printf("\033[1;1H");
+        printf("%s\n", message);
+        printf("\033[?1049l");
+    }
+    
+    return 0;
+}
